    public static void test_robots() {
        /* Test robots.txt parsing */
        assert spider.get_rules("1234") == null;

        String robots_url = "https://example.org/robots.txt";

        assert spider.parse_robots(robots_url, null) == null;
        assert spider.parse_robots(robots_url, 123) == null;
        assert spider.parse_robots(robots_url, "123") == null;

        var rules = spider.parse_robots(robots_url, "Allow: *");
        assert rules;
        assert rules.can_fetch("*", "https://example.org/1");

        rules = spider.parse_robots(robots_url, "User-agent: *\nDisallow: /");
        assert rules;
        assert !rules.can_fetch("*", "https://example.org/1");

        rules = spider.parse_robots(robots_url, "User-agent: *\nDisallow: /private");
        assert rules;
        assert !rules.can_fetch("*", "https://example.org/private");
        assert rules.can_fetch("*", "https://example.org/public");

        rules = spider.parse_robots(robots_url, "Allow: *\nUser-agent: *\nCrawl-delay: 10");
        assert rules;
        assert rules.crawl_delay("*") == 10;
    }
